  vec4 ret = vec4(0.0);
  vec2 uv = vUv;
  float rad = vRadius;


vec2 uv1 = (vUv-.5);// * uAspect.xy;

vec2 uv6 = uv1;
float z = 12*length((abs(uv1.x)-abs(uv1.y)));
vec2 d = normalize(uv1);
vec2 rs = clamp(tan(z)*d,-3,3);
uv1 -= rs/40;

uv6 = .4*cos(uv1*14+uTime);
mus = .004/(length(uv6));

vec3 crisp= texture(sampler_main,(uv1)*(.95-q28/16+.4*z)+.5);

vec3 ret1 = crisp + mus;

ret = (ret1*.99-.03);


  fragColor = ret;
